Under certain assumptions, Jensen \& Grotberg \cite{JG} applied the lubrication approximation and cross-sectional averaging to derive the following system of evolution equations for the film height $h=h(t ,x)$ and the surfactant concentration $\Gamma=\Gamma(t,x)$:

\begin{subequations} \begin{alignat}{2}
		\partial_t h &=-\partial_x \left[ \frac{h^2}{2}\partial_x \sigma(\Gamma)-\frac{\mathcal{G}}{3}h^3\partial_x h + \frac{\mathcal{S}}{3}h^3\partial_x^3h+\mathcal{A}\frac{\partial_x h}{h} \right]\; && \mbox{in}\quad \Omega_T\\
		\partial_t \Gamma &=- \partial_x \left[\Gamma \left(h \partial_x \sigma(\Gamma)-\frac{\mathcal{G}}{2} h^2 \partial_x h +\frac{\mathcal{S}}{2} h^2 \partial_x^3 h + \frac{3\mathcal{A}}{2} \frac{\partial_x h }{h^{2}}\right)-\mathcal{D}\partial_x \Gamma \right]\;\qquad&&  \mbox{in}\quad \Omega_T.
	\end{alignat}
\end{subequations}

For  $n\in {\mathbb N}$ we denote by
\begin{equation} W^{n,p}({\mathbb T})=\left\{u\in L^p({\mathbb T})\text{ such that } \|u\|_{W^{n,p}({\mathbb T})}^p:= \|u\|_{L^p}^p+\|\partial_x^n u\|_{L^p}^p<\infty
\right\}
\end{equation}
the standard $L^p$-based Sobolev spaces on ${\mathbb T}$.

We introduce the Wiener spaces $\dot{A}^s({\mathbb T})$ as
\begin{equation} \dot{A}^s({\mathbb T})=\left\{u\in L^1({\mathbb T})\text{ such that } \|u\|_{\dot{A}^s({\mathbb T})}:=\sum_{k\in{\mathbb Z}} |k|^s|\hat{u}(k)| < \infty\right\}.
\end{equation}

Let $p\geq q\geq 0$, then
\begin{equation} \|f\|_{ \dot A^q }\leq \|f\|_{ \dot A^p} \text{ for all } f\in  \dot A^p({\mathbb T}).
\end{equation}

Due to the H\"older inequality, we have the following interpolation inequality
\begin{equation} \|f\|_{\dot{A}^{s\theta}}\leq \|f\|_{\dot A^0}^{1-\theta}\|f\|_{\dot{A}^{s}}^{\theta}\quad \mbox{for all }\quad 0<\theta<1.
\end{equation}

Then, system \eqref{eq:system} is given by 
\begin{subequations} \begin{alignat}{2}
	\partial_t h &=-\partial_x \left[ -\frac{h^2}{2}\partial_x\Gamma-\frac{\mathcal{G}}{3}h^3\partial_x h + \frac{\mathcal{S}}{3}h^3\partial_x^3h+\mathcal{A}\frac{\partial_x h}{h} \right],\; &&\mbox{in}\quad \Omega_T \\
	\partial_t \Gamma &=- \partial_x \left[\Gamma \left(-h \partial_x \Gamma-\frac{\mathcal{G}}{2} h^2 \partial_x h +\frac{\mathcal{S}}{2} h^2 \partial_x^3 h + \frac{3\mathcal{A}}{2} \frac{\partial_x h }{h^{2}}\right)-\mathcal{D}\partial_x \Gamma \right],\;&&\mbox{in}\quad \Omega_T,
	\end{alignat}
\end{subequations}
with initial conditions
\[
h(0,x)=h_0(x)\quad \mbox{and}\quad \Gamma(0,x)=\Gamma_0(x)\qquad \mbox{for all} \quad x\in \Omega,
\]
and  boundary conditions
\begin{equation} \partial_x h =\partial_x \Gamma=0, \quad \mathcal{S}\partial_x^3 f =0 \qquad \mbox{for all}\quad x\in \partial \Omega.
\end{equation}

In the new variables \eqref{newunknown}, the system \eqref{eq:systemA} can be rewritten as
\begin{subequations} \begin{alignat}{2}
\partial_t f-\frac{h_\sharp^2}{2}\partial_x^2 \Theta +\left(\frac{\mathcal{A}}{h_\sharp}-\frac{\mathcal{G}}{3}h_\sharp^3\right)\partial_x^2 f+\frac{\mathcal{S}}{3}h_\sharp^3\partial_x^4 f&=\sum_{j=1}^4 N_j,\; &&\mbox{in}\quad (0,T)\times {\mathbb T}\\
\partial_t \Theta -\left(h_\sharp\Gamma_\sharp+\mathcal{D}\right)\partial_x^2\Theta+\left(\frac{3\mathcal{A}\Gamma_\sharp}{2h_\sharp^2}-\frac{\mathcal{G}}{2}\Gamma_\sharp h_\sharp^2\right) \partial_x^2f+\frac{\mathcal{S}}{2}\Gamma_\sharp h_\sharp^2 \partial_x^4f &= \sum_{j=5}^8 N_j,\;&& \mbox{in}\quad (0,T)\times {\mathbb T}
\end{alignat}
\end{subequations}
with initial conditions
\[
f(0,x)=f_0(x)\quad \mbox{and}\quad \Theta(0,x)=\Theta_0(x)\qquad \mbox{for all} \quad x\in \Omega,
\]
where $f_0(x)=h_0(x)-h_\sharp$ and $\Theta_0(x)=\Gamma_0(x)-\Gamma_\sharp$ are the initial displacement functions from the flat states $h_\sharp$ and $\Gamma_\sharp$, respectively.

Note that, for $|r|<1$, we have
\begin{align}
\frac{1}{1+r}&=\sum_{j=1}^\infty (-1)^{j+1}r^{j-1}, \\
\frac{1}{\left(1+r\right)^2}&=\sum_{j=1}^\infty j(-1)^{j+1}r^{j-1}, \\
\frac{1}{\left(1+r\right)^3}&=\frac{1}{2}\sum_{j=2}^\infty j(j-1)(-1)^{j}r^{j-2}. \end{align}

Consequently, under the assumption that
\begin{equation} \|f\|_{L^\infty}\leq \|f\|_{\dot A^0}< h_\sharp,
\end{equation}
 we can use \eqref{eq:taylor1} and \eqref{eq:taylor2} and write
\begin{align}
N_4&=\mathcal{A} \bigg{[}\left(\frac{f}{h_\sharp^2}\partial_x^2 f +\left(\frac{\partial_x f}{h_\sharp}\right)^2\right)\sum_{j=1}^\infty (-1)^{j+1}\left(\frac{f}{h_\sharp}\right)^{j-1}-\frac{f}{h_\sharp^3}(\partial_x f)^2\sum_{j=1}^\infty j(-1)^{j+1}\left(\frac{f}{h_\sharp}\right)^{j-1} \bigg{]}. \end{align}

Set $\zeta=3$ for the capillary driven flow ($\mathcal{S}>0$) and $\zeta=1$ for the gravity driven flow ($\mathcal{S}=0$).We say that $(f,\Theta)\in \left(L^1(0,T;W^{\zeta,1}({\mathbb T}))\right)^2$ is a weak solution of (\ref{eq:systemlinearized}) on $[0,T)$ corresponding to initial data $(f_0,\Theta_0)$ if and only if
\begin{align*}
-\int_{\mathbb T} f_0\phi(0)dx&-\int_0^T\int_{\mathbb T} f\partial_t\phi dxdt+\int_0^T\int_{\mathbb T} \partial_x^2\phi\left(-\frac{h_\sharp^2}{2}\Theta +\left(\frac{\mathcal{A}}{h_\sharp}-\frac{\mathcal{G}}{3}h_\sharp^3\right)f\right)  dxdt\\
&+\int_0^T\int_{\mathbb T}\partial_x^4\phi \frac{\mathcal{S}}{3}h_\sharp^3f dxdt+\sum_{j=1}^4\int_0^T\int_{\mathbb T}  \partial_x^{-1}N_j\partial_x \phi dxdt =0
\end{align*}
and
\begin{align*}
-\int_{\mathbb T} \Theta_0\psi(0)dx&-\int_0^T\int_{\mathbb T} \Theta\partial_t\psi dxdt+\int_0^T\int_{\mathbb T} \partial_x^2\psi\left(-\left(h_\sharp\Gamma_\sharp+\mathcal{D}\right)\Theta+\left(\frac{3\mathcal{A}\Gamma_\sharp}{2h_\sharp^2}-\frac{\mathcal{G}}{2}\Gamma_\sharp h_\sharp^2\right)f\right)  dxdt\\
&+\int_0^T\int_{\mathbb T}\partial_x^4\psi\frac{\mathcal{S}}{2} \Gamma_\sharp h_\sharp^2f dxdt+\sum_{j=5}^8\int_0^T\int_{\mathbb T}  \partial_x^{-1}N_j\partial_x \psi dxdt =0
\end{align*}
for all $(\phi,\psi)\in C^{\infty}_c([0,T)\times {\mathbb T})$,  where $\partial_x^{-1}$ denotes the operator given by $\widehat{\partial_x^{-1}u}(n)=-\frac{i}{n}\hat{u}(n)$.

Let $r,s\geq 0$. For $(f,\Theta):[0,T) \to \dot A^r({\mathbb T})\times \dot A^s({\mathbb T})$, we define the following functional:
\begin{equation} \mathscr{E}^r_{s}(f,\Theta):[0,T) \to [0,\infty),\qquad \mathscr{E}^r_{s}(f,\Theta)(t):=\|f(t)\|_{\dot{A}^r}+\|\Theta(t)\|_{\dot{A}^s}.
\end{equation}

To this end, let us define
\begin{align}
\Lambda_1(t)&:= h_\sharp+\frac{19h_\sharp^2\mathcal{ G}}{3}+ \frac{\mathcal{A}}{h_\sharp^2}\left(1-\frac{\mathscr{E}_0^0(f,\Theta)(t)}{h_\sharp}\right)^{-1}\bigg{[}2+\left(1-\frac{\mathscr{E}_0^0(f,\Theta)(t)}{h_\sharp}\right)^{-1} \bigg{]}+\Gamma_\sharp\nonumber \\ 
&\quad+\mathcal{G}\left(4\Gamma_\sharp h_\sharp +5h_\sharp^2\right)+\frac{3\mathcal{A}}{2h_\sharp^3}\left(1-\frac{\mathscr{E}_0^0(f,\Theta)(t)}{h_\sharp}\right)^{-2}\Big\{7\Gamma_\sharp + \frac{3}{2}h_\sharp + \left(1-\frac{\mathscr{E}_0^0(f,\Theta)(t)}{h_\sharp}\right)^{-1}4\Gamma_\sharp\Big\} ,\\
\Lambda_2(t)&:=\frac{13}{2}h_\sharp+2\Gamma_\sharp+\mathcal{G}h_\sharp^2+\frac{3\mathcal{A}}{2h_\sharp^3}\left(1-\frac{\mathscr{E}_0^0(f,\Theta)(t)}{h_\sharp}\right)^{-2}\frac{h_\sharp}{2} \,,
\end{align}
and the constants
\begin{align}
\mathfrak{C}_1&:=\frac{\mathcal{G}}{3}h_\sharp^3-\frac{\mathcal{A}}{h_\sharp}-\left|\frac{3\mathcal{A}\Gamma_\sharp}{2h_\sharp^2}-\Gamma_\sharp h_\sharp^2\frac{\mathcal{G}}{2}\right|, \\
\mathfrak{C}_2&:=h_\sharp \Gamma_\sharp+\mathcal{D}-\frac{h_\sharp^2}{2}. \end{align}

In addition to \eqref{eq:Lambda_1}--\eqref{constant2}, we define
{\begin{align}
\Lambda_3&:=\frac{\mathcal{S}}{2} (14h_\sharp\Gamma_\sharp +4h_\sharp^2)+\frac{19}{3}\mathcal{S}h_\sharp^2, \\
\mathfrak{C}_3&:=\frac{\mathcal{S}}{3}h_\sharp^3-\Gamma_\sharp h_\sharp^2\frac{\mathcal{S}}{2} .
\end{align}

We compute
\begin{align*}
\partial_t|\hat{f}(k)| &=\frac{\text{Re}\left(\bar{\hat{f}}(k)\partial_t\hat{f}(k)\right)}{|\hat{f}(k)|},
\end{align*}
so, using that $\mathcal{S}=0$,
\begin{align}
\frac{d}{dt}\|f\|_{\dot A^0}&\leq\frac{h_\sharp^2}{2}\|\Theta\|_{\dot{A}^2} +\left(\frac{\mathcal{A}}{h_\sharp}-\frac{\mathcal{G}}{3}h_\sharp^3\right)\| f\|_{\dot{A}^2}+\|N_1\|_{\dot A^0}+\|N_2\|_{\dot A^0}+\|N_4\|_{\dot A^0} ,\\
\frac{d}{dt}\|\Theta\|_{\dot A^0}&\leq-\left(h_\sharp \Gamma_\sharp+\mathcal{D}\right)\|\Theta\|_{\dot{A}^2}+\left|\frac{3\mathcal{A}\Gamma_\sharp}{2h_\sharp^2}-\Gamma_\sharp h_\sharp^2\frac{\mathcal{G}}{2}\right| \|f\|_{\dot{A}^2}+\|N_5\|_{\dot A^0}+\|N_6\|_{\dot A^0}+\|N_8\|_{\dot A^0} \end{align}

Similarly,
the nonlinear terms $N_j$, $j=5,6,$ and $8$ are bounded by
\begin{align*}
\|N_5\|_{\dot A^0}

&\leq \left(\Gamma_\sharp\|f\|_{\dot A^0}+\left(4h_\sharp+\Gamma_\sharp\right)\|\Theta\|_{\dot A^0} \right)\|\Theta\|_{\dot{A}^2}+ \Gamma_\sharp\|f\|_{\dot A^0}\|f\|_{\dot{A}^2}\\
&\leq \mathscr{E}_0^0(f,\Theta)\left(4h_\sharp+2\Gamma_\sharp \right)\|\Theta\|_{\dot{A}^2}+ \Gamma_\sharp\mathscr{E}_0^0(f,\Theta)\|f\|_{\dot{A}^2}\,,\end{align*}

We recall the definition \eqref{constant1} and \eqref{constant2}, then we add equations \eqref{eq:1} and \eqref{eq:2}, use the previous estimates for $N_j$, $j=1,2,4,5,6,$ and 8 and  obtain that
\begin{align} \frac{d}{dt}\mathscr{E}_0^0(f,\Theta)(t)&\leq -\left(\mathfrak{C}_1-\Lambda_1(t)\mathscr{E}_0^0(f,\Theta)(t)\right)\|f(t)\|_{\dot{A}^2}-\left(\mathfrak{C}_2-\Lambda_2(t)\mathscr{E}_0^0(f,\Theta)(t)\right)\|\Theta(t)\|_{\dot{A}^2}
\end{align}
 for $t\in[0,t_*)$,
with $\Lambda_1$ and $\Lambda_2$ defined in \eqref{eq:Lambda_1} and \eqref{eq:Lambda_2},  respectively.

Furthermore, the approximated problems provide the same \emph{a priori} bounds as in the previous sections.  Consequently the Galerkin solutions  $(f_M,\Theta_M)_{M\in {\mathbb N}}$ exist globally and for any $T>0$ we have the bounds:
\begin{equation} (f_M,\Theta_M)_{M\in{\mathbb N}} \quad \mbox{is uniformly bounded in}\quad \left( L^\infty\left(0,T;\dot A^0({\mathbb T})\right)\cap L^1\left(0,T; \dot A^2({\mathbb T}) \right)\right)^2
\end{equation}
and
\begin{equation} (\partial_t f_M,\partial_t\Theta_M)_{M\in{\mathbb N}} \quad \mbox{is uniformly bounded in}\quad \left( L^1\left(0,T; \dot A^0({\mathbb T}) \right)\right)^2.
\end{equation}

Using \eqref{eq:energyE} and the definition of $\delta>0$ in \eqref{delta}, we have that
\begin{align} \frac{d}{dt}\mathscr{E}^0_0(f_M,\Theta_M)(t)\leq -\delta\mathscr{E}^2_2(f_M,\Theta_M)(t) \qquad \mbox{for all}\quad t\geq0.
\end{align}

Using \eqref{eq:Linf1} and the lower semi-continuity of the weak$-*$ convergence, we have that
\begin{equation*}
\|f(t)\|_{L^\infty({\mathbb T})}+\|\Theta(t)\|_{L^\infty({\mathbb T})}\leq \liminf_{k\to \infty}\mathscr{E}_0^0(f_M,\Theta_M)(t)\leq 	\mathscr{E}_0^0(f_0,\Theta_0)e^{-\delta t}.
\end{equation*}

Using the smallness of the initial data, the same estimates as in Subsection \ref{ss:e} yield that
\begin{multline*}
\frac{d}{dt}\left(\|f_1-f_2\|_{\dot A^0}+\|\Theta_1-\Theta_2\|_{\dot A^0}\right)\\
\leq C\left[\|f_1-f_2\|_{\dot A^0}+\|\Theta_1-\Theta_2\|_{\dot A^0}\right]\left(\|f_1\|_{\dot A^2}+\|f_2\|_{\dot A^2}+\|\Theta_1\|_{\dot A^2}+\|\Theta_2\|_{\dot A^2}+1\right).
\end{multline*}

Similar as before, we have that
\begin{align}
\frac{d}{dt}\|f\|_{\dot A^0}&\leq\frac{h_\sharp^2}{2}\|\Theta\|_{\dot{A}^2} +\left(\frac{\mathcal{A}}{h_\sharp}-\frac{\mathcal{G}}{3}h_\sharp^3\right)\| f\|_{\dot{A}^2} - \frac{\mathcal{S}}{3}h_\sharp^3\|f\|_{\dot A^4}+\sum_{j=1}^4\|N_j\|_{\dot A^0} ,\\
\frac{d}{dt}\|\Theta\|_{\dot A^0}&\leq-\left(h_\sharp \Gamma_\sharp+\mathcal{D}\right)\|\Theta\|_{\dot{A}^2}+\left|\frac{3\mathcal{A}\Gamma_\sharp}{2h_\sharp^2}-\Gamma_\sharp h_\sharp^2\frac{\mathcal{G}}{2}\right|\|f\|_{\dot A^2}+\frac{\mathcal{S}}{2}h_\sharp^2\Gamma_\sharp\|f\|_{\dot A^4} +\sum_{j=5}^8\|N_j\|_{\dot A^0}. \end{align}

Thus we are left to estimate the remaining terms $\|N_3\|_{\dot A^0}$ and $\|N_7\|_{\dot A^0}$. Similarly as before, using the interpolation inequality in Wiener spaces, we estimate
\begin{align*}
\|N_3\|_{\dot A^0}&\leq \frac{19}{3}\mathcal{S}h_\sharp^2\mathscr{E}_0^0(f,\Theta)\|f\|_{\dot{A}^4},
\end{align*}

Using \eqref{eq:Lambda_3}, we can group terms as follows:
\begin{align*}
\frac{d}{dt}\mathscr{E}^0_0(f,\Theta)(t)&\leq -\left(\mathfrak{C}_1-\Lambda_1(t)\mathscr{E}^0_0(f,\Theta)(t)\right)\|f(t)\|_{\dot{A}^2}-\left(\mathfrak{C}_2-\left(\Lambda_2(t)+\frac{\mathcal{S}h_\sharp^2}{2}\right)\mathscr{E}^0_0(f,\Theta)(t)\right)\|\Theta(t)\|_{\dot{A}^2}\\
&\quad-\left(\mathfrak{C}_3-\Lambda_3\mathscr{E}^0_0(f,\Theta)(t)\right)\|f(t)\|_{\dot{A}^4}.
\end{align*}

Repeating the argument from Section \ref{S:T1}, we conclude  that
\begin{equation} \mathscr{E}^0_0(f,\Theta)(t)\leq \mathscr{E}^0_0(f_0,\Theta_0)e^{-\delta t} 
\end{equation}
where $\delta$ is defined in \eqref{delta}. The energy estimate for the capillary driven thin film ($\mathcal S >0$) reads
\begin{equation*}
\mathscr{E}^0_0(f,\Theta)(t)+ \int_0^t\delta \mathscr{E}^4_2(f,\Theta)(\tau)\, d\tau \leq \mathscr{E}^0_0(f_0,\Theta_0)
\end{equation*}
and
\[
\int_0^t \|\partial_t f(\tau)\|_{\dot A^0}+\|\partial_t \Theta(\tau)\|_{\dot A^0}\,d\tau \leq c,
\]
for all $t\in[0,T)$, where $c>0$ is a constant depending on the initial data.

Consequently, we obtain the existence of a subsequence (not relabeled) such that
\begin{align} \begin{split}
&f_M\rightharpoonup  f\text {   in $L^{\frac{4}{s}}(0,T; W^{s,p}({\mathbb T}))$},\quad 0\leq s<4,\;\;1\leq p<\infty\\
&\Theta_M\rightharpoonup  \Theta\text {   in $L^{\frac{2}{r}}(0,T; W^{r,p}({\mathbb T}))$} ,\quad 0\leq r<2,\;\;1\leq p<\infty.
\end{split}
\end{align}
Moreover,
\begin{align*}
f_M&\rightarrow f\qquad \text{ in $L^1(0,T;C^{3+\alpha}({\mathbb T}))$}, \quad \,0\leq \alpha<\frac{1}{2},\\
f_M&\rightharpoonup f\qquad \text{ in $L^2(0,T, H^2({\mathbb T}))$}
\end{align*}
and 
\begin{align*}
\Theta_M&\rightarrow \Theta\qquad \text{ in $L^1(0,T;C^{1+\alpha}({\mathbb T}))$},\quad  \,0\leq \alpha<\frac{1}{2},\\
\Theta_M&\rightharpoonup \Theta\qquad \text{ in $L^2(0,T, H^1({\mathbb T}))$}.
\end{align*}

Using \eqref{eq:Linf} and the lower semi-continuity of the weak$-*$ convergence, we have that
 \begin{equation*}
 \|f(t)\|_{L^\infty({\mathbb T})}+\|\Theta(t)\|_{L^\infty({\mathbb T})}\leq \liminf_{k\to \infty}\mathscr{E}^0_0(f_M,\Theta_M)(t)\leq 	\mathscr{E}_0^0(f_0,\Theta_0)e^{-\delta t}
 \end{equation*}
for all $t\geq 0$, which proves the claim.

Similar as for the energy estimate we compute that
 \begin{multline*}
 \frac{d}{dt}\left(\|f_1-f_2\|_{\dot A^0}+\|\Theta_1-\Theta_2\|_{\dot A^0}\right)\\
 \leq C \left[\|f_1-f_2\|_{\dot A^0}+\|\Theta_1-\Theta_2\|_{\dot A^0}\right]\\
 \times\left(\|f_1\|_{\dot A^2}+\|f_2\|_{\dot A^2}+\|f_1\|_{\dot A^4}+\|f_2\|_{\dot A^4}+\|\Theta_1\|_{\dot A^2}+\|\Theta_2\|_{\dot A^2}\right).
 \end{multline*}
